contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test that owner's withdraw(uint) either reverts or transfers exactly that amount out of C to the caller
    // amount: requested withdrawal amount
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // this test contract deployed C so it is the owner; ensure it has enough balance only if we will send Ether to C
        // require true as no precondition on amount
        require(true);

        // Observe before-values
        uint cBalBefore = address(c).balance;
        uint ownerBalBefore = address(this).balance;
        bool reverted;

        // Make the state-changing call as a top-level statement
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after-values
        uint cBalAfter = address(c).balance;
        uint ownerBalAfter = address(this).balance;

        // General rule: if the withdraw call did not revert, then C's balance decreased by exactly amount (but not below zero)
        // and the caller's balance increased by exactly amount. If it reverted, balances unchanged.
        // Expressed without underflow: when not reverted, cBalBefore >= amount and cBalBefore - cBalAfter == amount and ownerBalAfter == ownerBalBefore + amount;
        // when reverted, balances unchanged.
        assert(
            (reverted && cBalAfter == cBalBefore && ownerBalAfter == ownerBalBefore)
            ||
            (!reverted && cBalBefore >= amount && cBalAfter + amount == cBalBefore && ownerBalAfter == ownerBalBefore + amount)
        );
    }

    // Allow receiving Ether so withdraw can transfer to this contract
    receive() external payable {}
}

